style.css:
/* Pastel Harmony — All websites */
/* i really want this to be global */

:root {
  /* Swap these colours to customise your theme */
  --my-background: #F3EFF8;
  --my-surface: #FDFBFF;
  --my-blue: #DCEAF7;
  --my-yellow: #FFF2CC;
  --my-pink: #F2DFE8;
  --my-lavender: #E4DDF3;
  --my-sage: #DCE9DF;
  --my-text: #48434F;
  --my-link: #79668F;
  --my-border: #DDD5E7;
  --my-radius: 10px;
}

/* Soft page background */
html, body {
  background-color: var(--my-background) !important;
  color: var(--my-text) !important;
}

/* Lavender headers and sidebar */
header, nav {
  background-color: var(--my-lavender) !important;
  color: var(--my-text) !important;
}

/* Clean content areas */
article, aside, dialog {
  background-color: var(--my-surface) !important;
  border-radius: var(--my-radius) !important;
}

/* Pastel blue buttons */
button, input[type="button"], input[type="submit"] {
  background-color: var(--my-blue) !important;
  color: var(--my-text) !important;
  border-color: var(--my-border) !important;
  border-radius: var(--my-radius) !important;
}

/* Mixed pastel navigation buttons */
nav button:nth-child(4n+1) {
  background-color: var(--my-blue) !important;
}

nav button:nth-child(4n+2) {
  background-color: var(--my-pink) !important;
}

nav button:nth-child(4n+3) {
  background-color: var(--my-yellow) !important;
}

nav button:nth-child(4n) {
  background-color: var(--my-sage) !important;
}

/* Pink new chat button */
#sidebar a[href="/"] {
  background-color: var(--my-pink) !important;
  border-radius: var(--my-radius) !important;
}

/* Sage selected navigation items */
nav a[aria-current="page"] {
  background-color: var(--my-sage) !important;
  border-radius: var(--my-radius) !important;
}

/* Soft hover effect */
button:hover, nav button:hover, aside button:hover {
  background-color: var(--my-sage) !important;
}

/* Soft input fields */
input:not([type]), input[type="text"],
input[type="search"], textarea, select {
  background-color: var(--my-surface) !important;
  color: var(--my-text) !important;
  border-color: var(--my-border) !important;
  border-radius: var(--my-radius) !important;
}

/* Muted purple links */
a {
  color: var(--my-link) !important;
}

/* Pastel table headings */
th {
  background-color: var(--my-lavender) !important;
  color: var(--my-text) !important;
}

/* Butter yellow text highlighting */
::selection {
  background-color: var(--my-yellow) !important;
  color: var(--my-text) !important;
}
